/** What the old selects wrap their anchor, value and addon in. `hidden` while the value is shown in its place, which collapses the anchor. */
export const SelectWrapper = ({ hidden, children }: PartProps & { hidden?: boolean }) => (
	<SelectWrapperFrame className={`rcx-box rcx-box--full rcx-select__wrapper${hidden ? ' rcx-select__wrapper--hidden' : ''}`}>
		{children}
	</SelectWrapperFrame>
);

/** The field of a select that shows its selected options as chips. */
export const SelectField = ({ children }: PartProps) => (
	<SelectFieldFrame className='rcx-box rcx-box--full rcx-select__field'>{children}</SelectFieldFrame>
);

/** The chips and the anchor of a multiple select. */
export const SelectValues = ({ spacious, role, children }: PartProps & { spacious?: boolean; role?: AriaRole }) => (
	<SelectValuesFrame
		spacious={Boolean(spacious)}
		className={`rcx-box rcx-box--full rcx-select__values${spacious ? ' rcx-select__values--spacious' : ''}`}
		render={<div role={role} />}
	>
		{children}
	</SelectValuesFrame>
);

/** The selected label, or the placeholder, a select shows while its anchor is collapsed. */
export const SelectItem = ({ placeholder, medium, children }: PartProps & { placeholder?: boolean; medium?: boolean }) => (
	<SelectItemFrame
		tone={placeholder ? 'placeholder' : 'regular'}
		weight={medium ? 'medium' : 'regular'}
		className={`rcx-box rcx-box--full rcx-select__item${medium ? ' rcx-select__item--medium' : ''}${placeholder ? ' rcx-select__item--placeholder' : ''}`}
	>
		{children}
	</SelectItemFrame>
);

/** The text of a select's trigger. */
export const SelectValue = ({ placeholder, small, children }: PartProps & { placeholder?: boolean; small?: boolean }) => (
	<SelectValueFrame
		tone={placeholder ? 'placeholder' : 'regular'}
		small={Boolean(small)}
		className={`rcx-box rcx-box--full rcx-select__value${placeholder ? ' rcx-select__value--placeholder' : ''}${small ? ' rcx-select__value--small' : ''}`}
	>
		{children}
	</SelectValueFrame>
);
